Retrieves the details of a specific screen within a project.


exec tool declaration:
```ts
declare const tools: { mcp__StitchMCP__get_screen(args: {
  // Required. Identifier. The resource name of the screen to retrieve. Format: `projects/{project}/screens/{screen}` Example: `projects/4044680601076201931/screens/98b50e2ddc9943efb387052637738f61`
  name: string;
}): Promise<CallToolResult<{
  // The device type of the screen.
  deviceType?: "DEVICE_TYPE_UNSPECIFIED" | "MOBILE" | "DESKTOP" | "TABLET" | "AGNOSTIC";
  // The height of the screen.
  height?: string;
  // The HTML code of the screen.
  htmlCode?: {
  // Optional. The URL of the file for download. For image files, this would be FIFE base URLs. Only one of the following fields should be set: this field, uploadBlobId, fileContentBase64.
  downloadUrl?: string;
  // Optional. Input only. The base64-encoded string of the file content. Only one of the following fields should be set: this field, uploadBlobId, downloadUrl.
  fileContentBase64?: string;
  // Optional. The mime type of the file. E.g. "image/png", "text/html".
  mimeType?: string;
  // Identifier. The resource name of the file. Format: projects/{project}/files/{file}
  name?: string;
  // Optional. The BlobId from Scotty/contrib service file upload. This points to a temporary blobstore location of the file. Only one of the following fields should be set: this field, downloadUrl, fileContentBase64.
  uploadBlobId?: string;
  // Output only. The latest feedback submitted for the file.
  userFeedback?: {
  // Optional. Additional comment for the rating.
  comment?: string;
  // Optional. The reason for the feedback for a design, if the rating is negative.
  designFeedbackReason?: "DESIGN_FEEDBACK_REASON_UNSPECIFIED" | "DESIGN_DOESNT_MATCH_PROMPT" | "EDIT_DOESNT_MATCH_PROMPT" | "DESCRIPTION_DOESNT_MATCH" | "COMPONENT_ISSUE" | "INCORRECT_THEME" | "FIGMA_EXPORT_FAILED" | "OTHER";
  // Optional. The user rating of the interaction.
  rating?: "RATING_UNSPECIFIED" | "POSITIVE" | "NEGATIVE";
};
};
  // Identifier. The name of the screen. Format: projects/{project}/screens/{screen}
  name?: string;
  // The screenshot of the screen.
  screenshot?: {
  // Optional. The URL of the file for download. For image files, this would be FIFE base URLs. Only one of the following fields should be set: this field, uploadBlobId, fileContentBase64.
  downloadUrl?: string;
  // Optional. Input only. The base64-encoded string of the file content. Only one of the following fields should be set: this field, uploadBlobId, downloadUrl.
  fileContentBase64?: string;
  // Optional. The mime type of the file. E.g. "image/png", "text/html".
  mimeType?: string;
  // Identifier. The resource name of the file. Format: projects/{project}/files/{file}
  name?: string;
  // Optional. The BlobId from Scotty/contrib service file upload. This points to a temporary blobstore location of the file. Only one of the following fields should be set: this field, downloadUrl, fileContentBase64.
  uploadBlobId?: string;
  // Output only. The latest feedback submitted for the file.
  userFeedback?: {
  // Optional. Additional comment for the rating.
  comment?: string;
  // Optional. The reason for the feedback for a design, if the rating is negative.
  designFeedbackReason?: "DESIGN_FEEDBACK_REASON_UNSPECIFIED" | "DESIGN_DOESNT_MATCH_PROMPT" | "EDIT_DOESNT_MATCH_PROMPT" | "DESCRIPTION_DOESNT_MATCH" | "COMPONENT_ISSUE" | "INCORRECT_THEME" | "FIGMA_EXPORT_FAILED" | "OTHER";
  // Optional. The user rating of the interaction.
  rating?: "RATING_UNSPECIFIED" | "POSITIVE" | "NEGATIVE";
};
};
  // The title of the screen.
  title?: string;
  // The width of the screen.
  width?: string;
}>>; };
```

